        print_str(shifted_backward)
        print_bool(eq_str(word, shifted_backward))
        let shifted_twelve_forward = shift_letters(word, 12)
        print_str(shifted_twelve_forward)
        let restored = shift_letters(shifted_twelve_forward, 12)
        print_bool(eq_str(word, restored))
    }
}
fn shift_letters(s: Str, n: Int) -> Str {
    let chars = chars(s)
    let shifted_chars = map(chars, |c| {
        let base = if c >= 'a' && c <= 'z' { 'a' } else { 'A' }
        let offset = unwrap_or(unwrap_or(find(range('a', 'z'), |x| x == c), find(range('A', 'Z'), |x| x == c)), -1)
        let new_offset = (offset + n) % 26
        let new_char = add(base, new_offset)
        new_char
    })
    concat(shifted_chars)
}

